function assertScrollThresholdPercentOptional(scrollThresholdPercent: number | null | undefined,
    _label?: string) {
  let messages: AvoAssertMessage[] = [];
  if (scrollThresholdPercent !== undefined && scrollThresholdPercent !== null) {
    messages = messages.concat(AvoAssert.assertInt("Y4IZl7kPl8tnS4h_ZEafQ", _label ? "Scroll Threshold Percent" + ': ' + _label : "Scroll Threshold Percent", scrollThresholdPercent));
    messages = messages.concat(AvoAssert.assertMin("Y4IZl7kPl8tnS4h_ZEafQ", _label ? "Scroll Threshold Percent" + ": " + _label : "Scroll Threshold Percent", 0, scrollThresholdPercent));
    messages = messages.concat(AvoAssert.assertMax("Y4IZl7kPl8tnS4h_ZEafQ", _label ? "Scroll Threshold Percent" + ": " + _label : "Scroll Threshold Percent", 100, scrollThresholdPercent));
  }
  return messages;
}

function assertTotalDownloadableResources(totalDownloadableResources: number,
    _label?: string) {
  let messages: AvoAssertMessage[] = [];
  messages = messages.concat(AvoAssert.assertInt("v5S8At-_4BZ3vGl149_SP", _label ? "Total Downloadable Resources" + ': ' + _label : "Total Downloadable Resources", totalDownloadableResources));
  messages = messages.concat(AvoAssert.assertMin("v5S8At-_4BZ3vGl149_SP", _label ? "Total Downloadable Resources" + ": " + _label : "Total Downloadable Resources", 0, totalDownloadableResources));
  return messages;
}

